import hashlib, json, re
from pathlib import Path
base = Path('products/services/catalogue-commissioned-review')
records = []
for name in ('candidate-verification.json', 'qualified-inquiry-handoff-verification.json'):
    path = base / name
    raw = path.read_bytes()
    doc = json.loads(raw)
    evidence = []
    def scan(value, keys=()):
        if isinstance(value, dict):
            for key, item in value.items():
                scan(item, (*keys, key))
        elif isinstance(value, list):
            for i, item in enumerate(value):
                scan(item, (*keys, str(i)))
        elif isinstance(value, str):
            refs = re.findall(r'TASK-[0-9]{4,12}|[0-9a-f]{64}|price-update-review-(?:en|fr)', value)
            if refs or (keys and keys[-1] in {'mission_id', 'status', 'verdict', 'subject'} and re.fullmatch(r'[A-Za-z0-9:_-]{1,128}', value)):
                evidence.append({'field': '.'.join(keys), 'references': refs or [value]})
    scan(doc)
    records.append({'path': str(path), 'sha256': hashlib.sha256(raw).hexdigest(), 'references': evidence})
result = {'scope': 'References extracted from producer records. Match them to host receipts and exact digests before inferring review or deployment.', 'records': records}
out = Path('products/distribution/catalogue-example-baseline-reconciliation/price-review-record-references.json')
out.parent.mkdir(parents=True, exist_ok=True)
out.write_text(json.dumps(result, indent=2) + '\n', encoding='utf-8')
print(out.read_text(encoding='utf-8'))
